import{_ as t,o as n,c as o,ah as i}from"./chunks/framework.DDXs_i7t.js";const c=JSON.parse(`{"title":"The Day of Reckoning? Wöginger in the Witness Stand","description":"Examination of August Wöginger at the Linz Regional Court. We document today's trial day for the 'Horten Mystery'.","frontmatter":{"title":"The Day of Reckoning? Wöginger in the Witness Stand","description":"Examination of August Wöginger at the Linz Regional Court. We document today's trial day for the 'Horten Mystery'.","date":"2026-03-03T00:00:00.000Z"},"headers":[],"relativePath":"en/logbuch/2026-03-03-woeginger-im-zeugenstand.md","filePath":"en/logbuch/2026-03-03-woeginger-im-zeugenstand.md"}`),a={name:"en/logbuch/2026-03-03-woeginger-im-zeugenstand.md"};function r(s,e,g,h,d,l){return n(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="⚖️-the-day-of-reckoning-woginger-in-the-witness-stand" tabindex="-1">⚖️ The Day of Reckoning? Wöginger in the Witness Stand <a class="header-anchor" href="#⚖️-the-day-of-reckoning-woginger-in-the-witness-stand" aria-label="Permalink to &quot;⚖️ The Day of Reckoning? Wöginger in the Witness Stand&quot;">​</a></h1><p>Today, on <strong>March 03, 2026</strong>, all of Austria looked towards Linz. In Room 101 of the Regional Court, August Wöginger, one of the most powerful string-pullers in current politics, sat on the defendant&#39;s bench.</p><p><strong>Highlights of Today:</strong></p><ol><li><strong>The &quot;Not Guilty&quot; Plea:</strong> Wöginger was pugnacious. The diversion in 2025 was only a strategic retreat to protect his family, not an admission of wrongdoing.</li><li><strong>Late Regret or Tactical Maneuver?</strong> His statement &quot;I wouldn&#39;t do it again today&quot; marks an interesting turning point in his defense. He admits the mistake of the &quot;request for review,&quot; but denies the criminal intent behind it.</li><li><strong>The Fronts Harden:</strong> While the co-defendant Herbert B. describes Thomas Schmid&#39;s statements as a &quot;lie,&quot; everyone prepares for the duel on March 09, when Schmid himself will testify.</li></ol><p><strong>Mockumentary Context:</strong> In our film project, we use these scenes for the finale of Part 4. We ask the question: Where does the &quot;citizen concern&quot; end and where does the systematic subversion of the rule of law begin?</p><p><em>Satirical Element:</em> Today we sketched a scene in which Udo Samel (as Wöginger) tries to explain to a computer algorithm that an intervention is merely a &quot;human update&quot; of the database.</p><p><em>Documented by Gemini CLI. March 03, 2026 – The trial is ongoing.</em></p>',7)])])}const m=t(a,[["render",r]]);export{c as __pageData,m as default};
